    /// <summary>Go: <c>func getNodeCommonData(node *ast.Node) uint32</c>（encoder_generated.go:541-659）。</summary>
    internal static uint GetNodeCommonData(Node node)
    {
        switch (node.Kind)
        {
            case Kind.Block:
            {
                var n = node.AsBlock()!;
                return BoolToByte(n.MultiLine) << 24;
            }

            case Kind.HeritageClause:
            {
                var n = node.AsHeritageClause()!;
                var tokenIdx = 0u;
                switch (n.Token)
                {
                    case Kind.ImplementsKeyword:
                        tokenIdx = 1;
                        break;
                }

                return tokenIdx << 24;
            }

            case Kind.ExportAssignment:
            {
                var n = node.AsExportAssignment()!;
                return BoolToByte(n.IsExportEquals) << 24;
            }

            case Kind.ExportSpecifier:
            {
                var n = node.AsExportSpecifier()!;
                return BoolToByte(n.IsTypeOnly) << 24;
            }

            case Kind.PrefixUnaryExpression:
            {
                var n = node.AsPrefixUnaryExpression()!;
                var operatorIdx = 0u;
                switch (n.Operator)
                {
                    case Kind.MinusToken:
                        operatorIdx = 1;
                        break;
                    case Kind.TildeToken:
                        operatorIdx = 2;
                        break;
                    case Kind.ExclamationToken:
                        operatorIdx = 3;
                        break;
                    case Kind.PlusPlusToken:
                        operatorIdx = 4;
                        break;
                    case Kind.MinusMinusToken:
                        operatorIdx = 5;
                        break;
                }

                return operatorIdx << 24;
            }

            case Kind.PostfixUnaryExpression:
            {
                var n = node.AsPostfixUnaryExpression()!;
                var operatorIdx = 0u;
                switch (n.Operator)
                {
                    case Kind.MinusMinusToken:
                        operatorIdx = 1;
                        break;
                }

                return operatorIdx << 24;
            }

            case Kind.MetaProperty:
            {
                var n = node.AsMetaProperty()!;
                var keywordTokenIdx = 0u;
                switch (n.KeywordToken)
                {
                    case Kind.NewKeyword:
                        keywordTokenIdx = 1;
                        break;
                }

                return keywordTokenIdx << 24;
            }

            case Kind.ArrayLiteralExpression:
            {
                var n = node.AsArrayLiteralExpression()!;
                return BoolToByte(n.MultiLine) << 24;
            }

            case Kind.ObjectLiteralExpression:
            {
                var n = node.AsObjectLiteralExpression()!;
                return BoolToByte(n.MultiLine) << 24;
            }

            case Kind.TypeOperator:
            {
                var n = node.AsTypeOperatorNode()!;
                var operatorIdx = 0u;
                switch (n.Operator)
                {
                    case Kind.ReadonlyKeyword:
                        operatorIdx = 1;
                        break;
                    case Kind.UniqueKeyword:
                        operatorIdx = 2;
                        break;
                }

                return operatorIdx << 24;
            }

            case Kind.ImportAttributes:
            {
                var n = node.AsImportAttributes()!;
                var tokenIdx = 0u;
                switch (n.Token)
                {
                    case Kind.AssertKeyword:
                        tokenIdx = 1;
                        break;
                }

                return (BoolToByte(n.MultiLine) << 24) | (tokenIdx << 25);
            }

            case Kind.SyntheticExpression:
                return GetNodeCommonData_SyntheticExpression(node);

            case Kind.JsxText:
            {
                var n = node.AsJsxText()!;
                return BoolToByte(n.ContainsOnlyTriviaWhiteSpaces) << 24;
            }

            case Kind.ModuleDeclaration:
            {
                var n = node.AsModuleDeclaration()!;
                var keywordIdx = 0u;
                switch (n.Keyword)
                {
                    case Kind.NamespaceKeyword:
                        keywordIdx = 1;
                        break;
                }

                return keywordIdx << 24;
            }

            case Kind.ImportEqualsDeclaration:
            {
                var n = node.AsImportEqualsDeclaration()!;
                return BoolToByte(n.IsTypeOnly) << 24;
            }

            case Kind.ExportDeclaration:
            {
                var n = node.AsExportDeclaration()!;
                return BoolToByte(n.IsTypeOnly) << 24;
            }

            case Kind.ImportType:
            {
                var n = node.AsImportTypeNode()!;
                return BoolToByte(n.IsTypeOf) << 24;
            }

            case Kind.ImportClause:
            {
                var n = node.AsImportClause()!;
                var phaseModifierIdx = 0u;
                switch (n.PhaseModifier)
                {
                    case Kind.TypeKeyword:
                        phaseModifierIdx = 1;
                        break;
                    case Kind.DeferKeyword:
                        phaseModifierIdx = 2;
                        break;
                }

                return phaseModifierIdx << 24;
            }

            case Kind.ImportSpecifier:
            {
                var n = node.AsImportSpecifier()!;
                return BoolToByte(n.IsTypeOnly) << 24;
            }

            case Kind.JSDocTypeLiteral:
            {
                var n = node.AsJSDocTypeLiteral()!;
                return BoolToByte(n.IsArrayType) << 24;
            }

            case Kind.JSDocParameterTag:
            case Kind.JSDocPropertyTag:
            {
                var n = node.AsJSDocParameterOrPropertyTag()!;
                return (BoolToByte(n.IsBracketed) << 24) | (BoolToByte(n.IsNameFirst) << 25);
            }
        }

        return 0;
    }

    /// <summary>Go: <c>func recordNodeStrings(node *ast.Node, strs *stringTable) uint32</c>（encoder_generated.go:661-680）。</summary>
    internal static uint RecordNodeStrings(Node node, StringTable strs)
    {
        switch (node.Kind)
        {
            case Kind.Identifier:
                return strs.Add(node.AsIdentifier()!.Text, node.Kind, node.Pos(), node.End());
            case Kind.PrivateIdentifier:
                return strs.Add(node.AsPrivateIdentifier()!.Text, node.Kind, node.Pos(), node.End());
            case Kind.JsxText:
                return strs.Add(node.AsJsxText()!.Text, node.Kind, node.Pos(), node.End());
            case Kind.JSDocText:
                return strs.Add(node.AsJSDocText()!.Text(), node.Kind, node.Pos(), node.End());
            case Kind.JSDocLink:
                return strs.Add(node.AsJSDocLink()!.Text(), node.Kind, node.Pos(), node.End());
            case Kind.JSDocLinkPlain:
                return strs.Add(node.AsJSDocLinkPlain()!.Text(), node.Kind, node.Pos(), node.End());
            case Kind.JSDocLinkCode:
                return strs.Add(node.AsJSDocLinkCode()!.Text(), node.Kind, node.Pos(), node.End());
            default:
                throw new DebugFailureException($"Unexpected node kind {node.Kind.String()}");
        }
    }

